-- Read only; returns counts/authority/consent summaries, never notes, email or tokens.
with targets(label, identity_sha256) as (values
('LEARNER_A','995e6d265987a1c5cd6c831d6b2dda54998092aa769082cc72bf93fa209ece68'),
('LEARNER_B','1dce191e95a843797bb7e8ebb9c63e5f0a5e20aa7ee98720be3df467421bebd3')),
actors as (select t.label,t.identity_sha256,u.id,u.email_confirmed_at from targets t left join auth.users u on encode(sha256(convert_to(u.id::text,'UTF8')),'hex')=t.identity_sha256)
select jsonb_build_object(
'capturedAt',clock_timestamp(),'kind','ManualNativeTrialProgressReadback','projectRef','mhumbczqrzutdnraafhs',
'ai',(select jsonb_build_object('enabled',enabled,'version',version_no,'modelUnset',model_id='') from private.ai_configurations where singleton),
'ownerDefinitionMd5',(select md5(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='mcy_ai_save_owner_config'),
'writerBodyMd5',(select md5(p.prosrc) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='save_my_checkin_for_current_user_with_current_consent'),
'writerDefinitionMd5',(select md5(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='save_my_checkin_for_current_user_with_current_consent'),
'ledgerApplied',(select count(*) from supabase_migrations.schema_migrations),
'actors',(select jsonb_agg(jsonb_build_object('label',a.label,'identitySha256',a.identity_sha256,'found',a.id is not null,'confirmed',a.email_confirmed_at is not null,'hasProfile',exists(select 1 from public.profiles p where p.user_id=a.id),
'activeStaffRoles',(select count(*) from private.role_assignments r where r.user_id=a.id and r.status='active' and r.starts_at<=clock_timestamp() and (r.ends_at is null or r.ends_at>clock_timestamp()) and r.revoked_at is null),
'activeTeacherProfile',exists(select 1 from public.teachers t where t.user_id=a.id and t.active),
'consentCount',(select count(*) from private.consent_events c where c.user_id=a.id),
'checkinCount',(select count(*) from public.checkins c where c.user_id=a.id),
'observationCount',(select count(*) from public.checkin_observations o where o.user_id=a.id),
'profileSummary',(select jsonb_build_object('locale',case when p.locale in ('vi','vi-VN','en','en-US') then p.locale else 'other' end,'bodyDisplayPreference',p.body_display_preference,'createdAt',p.created_at,'updatedAt',p.updated_at,'preparedDisplayNameMatches',p.display_name=case when a.label='LEARNER_A' then 'MCY Native QA A' else 'MCY Native QA B' end,'rowSha256',encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')) from public.profiles p where p.user_id=a.id),
'oldHistoryDigests',jsonb_build_object('consents',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(c) order by c.id)::text,'[]'),'UTF8')),'hex') from private.consent_events c where c.user_id=a.id and c.created_at<='2026-10-13T03:31:52.615701+00:00'::timestamptz),'checkins',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(c) order by c.id)::text,'[]'),'UTF8')),'hex') from public.checkins c where c.user_id=a.id and c.created_at<='2026-10-13T03:31:52.615701+00:00'::timestamptz),'observations',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(o) order by o.id)::text,'[]'),'UTF8')),'hex') from public.checkin_observations o where o.user_id=a.id and o.created_at<='2026-10-13T03:31:52.615701+00:00'::timestamptz)),
'newConsentRows',(select coalesce(jsonb_agg(jsonb_build_object('purpose',c.purpose,'action',c.action,'policyVersion',case when c.policy_version in ('terms-review-0.1','privacy-review-0.1','wellbeing-data-review-0.1','ai-processing-review-1.0','teacher-sharing-review-0.1','notifications-review-0.1','marketing-review-0.1') then c.policy_version else 'other' end,'source',c.source,'channel',case when c.evidence->>'channel' in ('web','ios','android') then c.evidence->>'channel' else 'other' end,'createdAt',c.created_at,'occurredAt',c.occurred_at,'idempotencyKeyPresent',c.idempotency_key is not null,'rowSha256',encode(sha256(convert_to(to_jsonb(c)::text,'UTF8')),'hex')) order by c.occurred_at,c.id),'[]'::jsonb) from private.consent_events c where c.user_id=a.id and c.created_at>'2026-10-13T03:31:52.615701+00:00'::timestamptz),
'newCheckinRows',(select coalesce(jsonb_agg(jsonb_build_object('bodyStatus',c.body_status,'captureType',c.capture_type,'energyLevel',c.energy_level,'noteAbsent',c.overall_note is null,'localDate',c.local_date,'timezone',case when exists(select 1 from pg_catalog.pg_timezone_names z where z.name=c.local_timezone) then c.local_timezone else 'other' end,'createdAt',c.created_at,'observationCount',(select count(*) from public.checkin_observations o where o.checkin_id=c.id),'rowSha256',encode(sha256(convert_to(to_jsonb(c)::text,'UTF8')),'hex')) order by c.created_at,c.id),'[]'::jsonb) from public.checkins c where c.user_id=a.id and c.created_at>'2026-10-13T03:31:52.615701+00:00'::timestamptz),
'newObservationCount',(select count(*) from public.checkin_observations o where o.user_id=a.id and o.created_at>'2026-10-13T03:31:52.615701+00:00'::timestamptz),
'historyDigests',jsonb_build_object('checkins',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(c) order by c.id)::text,'[]'),'UTF8')),'hex') from public.checkins c where c.user_id=a.id),'observations',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(o) order by o.id)::text,'[]'),'UTF8')),'hex') from public.checkin_observations o where o.user_id=a.id)),
'authMetadata', (select jsonb_build_object('nonLocaleSha256',encode(sha256(convert_to((coalesce(u.raw_user_meta_data,'{}'::jsonb)-'locale')::text,'UTF8')),'hex'),'appMetadataSha256',encode(sha256(convert_to(coalesce(u.raw_app_meta_data,'{}'::jsonb)::text,'UTF8')),'hex'),'locale',case when u.raw_user_meta_data->>'locale' in ('vi','vi-VN','en','en-US') then u.raw_user_meta_data->>'locale' else null end) from auth.users u where u.id=a.id),
'latestConsent',(select jsonb_agg(to_jsonb(c)) from (select distinct on (purpose) purpose,action,case when policy_version in ('terms-review-0.1','privacy-review-0.1','wellbeing-data-review-0.1','ai-processing-review-1.0','teacher-sharing-review-0.1','notifications-review-0.1','marketing-review-0.1') then policy_version else 'other' end as policy_version from private.consent_events where user_id=a.id order by purpose,occurred_at desc,id desc)c)
) order by a.label) from actors a)
) as receipt;
